class Message:
    def __init__(self, sender, content, timestamp):
        self.sender = sender
        self.content = content
        self.timestamp = timestamp

    def display(self):
        print(f'[{self.timestamp}] {self.sender}: {self.content}')

    def __str__(self):
        return f'{self.sender}: {self.content}'

class ChatChannel(Channel):
    def __init__(self, name, is_private=False):
        super().__init__(name)
        self.is_private = is_private

def next_car_duration(entry_number):
    if entry_number == 1:
        return 2
    elif entry_number == 2:
        return 3
    else:
        return next_car_duration(entry_number - 1) * next_car_duration(entry_number - 2)
